catalogs.kane-cli:
catalog: kane-cli
version: 3
metrics:
  self_heals: { type: count, verify: stored, merge: sum }
  perf.lcp_ms: { type: ms, verify: stored }
  flaky_rate: { type: ratio, range: [0, 1], verify: { expr: "1.0" } }
  browser: { type: enum, values: [chrome, firefox], verify: stored }
  healed_tests: { type: count, per_test: true, verify: { aggregate: count } }

clean.text:
policy: release-2.x
requires: { catalog: kane-cli, version: ">=1" }
gates:
  - { id: all-pass, metric: totals.failed, equals: 0, severity: blocking }
  - { id: heals, metric: metrics.self_heals, max: 3, severity: warning }
  - { id: lcp, metric: metrics.perf.lcp_ms, range: [0, 2500], severity: warning }
  - { id: rate, metric: pass_rate, where: "'checkout' in test.tags", min: 0.95, severity: blocking }
  - { id: browser, metric: metrics.browser, in: [chrome], severity: blocking }
  - { id: status, metric: run.status, equals: finalized, severity: blocking }
  - { id: flaky, expr: "tests.filter(t, 'critical' in t.tags).all(t, !t.flaky)", severity: blocking }

policy: p
gates:
  - { id: g, metric: pass_rate, where: "test.flaky", min: 0.5, severity: blocking }

policy: p
gates:
  - { id: g, expr: "sum([1, 2]) > 0 && mean([1.0, 2.0]) > 0.0 && percentile([1, 2, 3], 90) >= 1.0", severity: blocking }

policy: p
gates:
  - { id: g, expr: "double(run.duration_ms) > 1", severity: blocking }

policy: p
gates:
  - { id: g, expr: "totals.failed <= 0.0 || totals.failed < 1.5", severity: blocking }

policy: p
gates:
  - { id: g, expr: "size(tests) >= 1u", severity: blocking }

policy: p
gates:
  - { id: g, expr: "size(tests) > 0.5", severity: blocking }

policy: p
gates:
  - { id: g, expr: "run.branch.lowerAscii() == 'main'", severity: blocking }

policy: p
gates:
  - { id: g, expr: "run.branch.matches('^rel')", severity: blocking }

policy: p
gates:
  - { id: g, metric: metrics.healed_tests, max: 1, severity: blocking }

policy: shared-aliases
gates:
  - {id: g0, metric: pass_rate, where: &w "'checkout' in test.tags", min: 0.5, severity: &s blocking}
  - {id: g1, metric: pass_rate, where: *w, min: 0.5, severity: *s}
